// Authored room layouts and attack state machines. Loaded after adventure.js.
let gates=[],hazards=[],section=-1,checkpointState=null,tourPage=0,wave=0;
const roomBounds=[0,1050,2250,3200,4300,5500,6600];
const roomNames=['Docking bay','Maintenance shafts','Security checkpoint','Cooling chamber','Data archive','Anomaly hangar'];
const forestNames=['Moonlit approach','Root tunnels','Ruined watchtower','Flooded shrine','The broken library','Portal clearing'];
function buildOpening(){chapters[0].length=6600;solids=[{x:0,y:FLOOR,w:6600,h:110,kind:selected==='nova'?'metal':'wood'}];ladders=[];covers=[];actors=[];objects=[];gates=[];hazards=[];section=-1;checkpointState=null;
 const routes=selected==='nova'?[[220,280,520],[1100,380,230],[1470,300,260],[1870,220,210],[2400,260,360],[2860,340,230],[3280,300,340],[3710,220,340],[4070,340,180],[4370,360,360],[4740,260,310],[5090,200,270],[5580,300,420],[6040,230,330]]:[[180,330,390],[680,250,290],[1190,370,300],[1620,270,330],[1980,190,240],[2430,330,270],[2790,240,310],[3380,370,270],[3770,250,350],[4440,300,400],[4900,210,360],[5610,330,330],[6070,240,320]];
 for(const [x,y,w] of routes){solids.push({x,y,w,h:17,kind:selected==='nova'?'metal':'wood'});ladders.push({x:x+35,y,h:FLOOR-y});}
 for(const [x,w,h] of [[420,90,76],[800,125,66],[1180,60,60],[1740,100,85],[2320,95,82],[2580,140,68],[3020,65,75],[3440,100,78],[3970,75,66],[4540,130,80],[5280,80,66],[5730,95,76]])covers.push({x,y:FLOOR-h,w,h});
 const stations=selected==='nova'?[[1990,200,'key'],[2670,240,'security'],[3910,200,'cooling'],[4940,240,'data']]:[[2070,170,'key'],[2930,220,'security'],[3950,230,'cooling'],[5050,190,'data']];
 for(const [x,y,action] of stations)objects.push({type:action==='key'?'key':'terminal',id:action,action,x,y});
 objects.push({type:'portal',x:6420,y:FLOOR-90},{type:'heart',x:3180,y:FLOOR-35},{type:'heart',x:5460,y:FLOOR-35},{type:'coin',x:650,y:250},{type:'coin',x:4500,y:330},{type:'coin',x:6170,y:210});
 gates=[{x:2250,requires:'key',name:selected==='nova'?'ACCESS CARD':'MOON SEAL'},{x:3200,requires:'security',name:selected==='nova'?'SECURITY LOCK':'WATCHTOWER WARD'},{x:4300,requires:'cooling',name:selected==='nova'?'COOLING LOCK':'SHRINE WARD'},{x:5500,requires:'data',name:selected==='nova'?'ARCHIVE LOCK':'LIBRARY WARD'}];
 for(const [x,y,r] of [[740,366,110],[1330,366,70],[2520,366,140],[2960,256,65],[3520,366,100],[4080,366,80],[4750,366,150],[5200,114,75],[5930,366,130]]){const e=enemy(x,selected==='nova'?'guard':'pirate',3);e.y=y;e.origin=x;e.range=r;actors.push(e);}
 hazards=[{x:3560,w:95,phase:0},{x:4030,w:85,phase:1.6}];
 talk(selected==='nova'?'Nova':'Sylvanas',selected==='nova'?'Six rooms between us and the anomaly. Maintenance has the access card. Take the upper route or stay behind cover.':'The moon seal lies above the root tunnels. Break the three wards beyond it. Then we shall see what tore open my world.',7);
}
function stationDone(id){return objects.some(o=>o.id===id&&o.done);}
function worldStep(dt){if(chapter!==0)return;for(const g of gates)if(!stationDone(g.requires)&&player.x+34>g.x&&player.x<g.x+25){player.x=g.x-35;talk('Locked',g.name+' · complete the objective in the previous room.',2);}
 const next=roomBounds.findIndex((b,i)=>i<6&&player.x>=b&&player.x<roomBounds[i+1]);if(next!==section&&next>=0){section=next;checkpointState={x:Math.max(85,roomBounds[next]+65),done:objects.filter(o=>o.done&&o.id).map(o=>o.id)};talk('Mission',`${next+1}/6 · ${(selected==='nova'?roomNames:forestNames)[next]} · checkpoint`,3);}
 for(const h of hazards)if(!stationDone('cooling')&&(clock+h.phase)%4<1.15&&player.x+34>h.x&&player.x<h.x+h.w&&player.y+86>(h.y||452)-40)hurt();
}
function openingHUD(){if(chapter!==0)return;const current=Math.max(0,section);$('#chapter').textContent=(selected==='nova'?roomNames:forestNames)[current];const todo=objects.find(o=>o.id&&!o.done);$('#objective').textContent=todo?`${current+1}/6 · ${selected==='nova'?({key:'Find the upper maintenance access card',security:'Disable checkpoint security',cooling:'Vent the cooling chamber',data:'Download the anomaly coordinates'})[todo.id]:({key:'Recover the moon seal',security:'Break the watchtower ward',cooling:'Drain the shrine',data:'Read the broken library'})[todo.id]}`:'Reach the anomaly · meet the other lady';}
function openingInteraction(o){if(o.type==='key'){o.done=true;tone(850,.2);talk(selected==='nova'?'Nova':'Sylvanas',selected==='nova'?'Access card. Security probably meant to leave that somewhere less convenient.':'The moon seal. The next gate will yield.');hud();return true;}if(o.type==='terminal'&&o.id){o.done=true;const lines={security:'Checkpoint lockdown disabled. Cooling chamber is open.',cooling:'Pressure vented. The data archive is accessible.',data:'Coordinates recovered. That portal leads straight into my hangar.'};talk(selected==='nova'?'Nova':'Sylvanas',selected==='nova'?lines[o.id]:'Another ward broken. Follow the upper passages to the next chamber.');tone(740,.2);hud();return true;}return false;}
function arrival(){const o=objects.find(o=>o.type==='portal');partner={x:o.x,y:FLOOR-86,w:34,h:86,face:-1,attack:0,arrival:2};mode='arrival';for(const k in keys)keys[k]=false;player.x=o.x-95;player.face=1;camera=chapters[0].length-VW;talk(selected==='nova'?'Sylvanas':'Nova',selected==='nova'?'Where am I—and why does your ceiling have stars?':'Pointy ears. Magic portal. Okay, your day might be weirder than mine.',3);}
function arrivalStep(dt){clock+=dt;partner.arrival=Math.max(0,partner.arrival-dt);timeTalk-=dt;if(timeTalk<=0){save.story=Math.max(save.story,1);persist();start(1);}}
function shipTour(){chapter=1;const text=[['Nova','Welcome aboard. Bridge, weapons locker, galley. Try not to curse the coffee machine.'],['Sylvanas','Your ship is tolerable. Your hospitality would improve with a drink.'],['Nova','There’s a bar at the spaceport. One drink. What could possibly go wrong?']];const [who,line]=text[tourPage];panel(`<p class="eyebrow">After the portal · aboard Nova’s ship</p><h2>${tourPage<2?'An unexpected guest':'An excellent bad idea'}</h2><div class="tour-picture"><img src="assets/ship-tour.webp" alt="Nova showing Sylvanas around her ship" style="transform:translateY(${tourPage===0?'0':'-50%'})"></div><p><b>${who}</b><br>${line}</p><button class="primary" id="tour-next">${tourPage===2?'Go get a drink':'Continue the tour →'}</button>`);$('#tour-next').onclick=()=>{tourPage++;if(tourPage>=3){save.story=Math.max(save.story,2);persist();start(2);}else shipTour();};}
function buildBrawl(){chapters[2].length=2200;solids=[{x:0,y:FLOOR,w:2200,h:110,kind:'wood'},{x:650,y:290,w:800,h:17,kind:'wood'}];ladders=[{x:690,y:290,h:162},{x:1410,y:290,h:162}];covers=[];objects=[{type:'exit',x:2080,y:FLOOR-50}];player.x=1000;partner.x=925;camera=660;wave=0;actors=[];const specs=[[430,'rush',0],[1510,'flank',0],[1850,'rush',0],[140,'flank',1],[1740,'rush',1],[2000,'thrower',1],[220,'rush',2],[1950,'flank',2],[1600,'bruiser',2]];for(const [x,role,w] of specs){const e=enemy(x,'brawler',role==='bruiser'?6:3);Object.assign(e,{role,wave:w,state:'approach',timer:0,inactive:w>0,attackHit:false,speed:role==='flank'?95:role==='bruiser'?45:65});actors.push(e);}talk('Nova','Three rounds of bad decisions. Watch the raised fist, step out of reach, then hit during recovery. Balcony gives you another way around.',6);}
function brawlerStep(e,dt){if(e.inactive||e.dead)return;e.stun=Math.max(0,e.stun-dt);e.timer=Math.max(0,e.timer-dt);const dx=player.x-e.x,dy=player.y-e.y;if(e.state==='approach'||e.state==='retreat')e.face=Math.sign(dx)||e.face;if(e.stun>0){e.state='recover';e.timer=.55;return;}if(e.state==='windup'){if(e.timer===0){e.state='strike';e.timer=.18;e.attackHit=false;}return;}if(e.state==='strike'){if(!e.attackHit){e.attackHit=true;if(!e.throwing&&Math.abs(dx)<90&&Math.abs(dy)<70&&dx*e.face>=0)hurt();}if(!e.timer){e.state='recover';e.timer=e.role==='bruiser'?1.2:.8;}return;}if(e.state==='recover'){if(!e.timer){e.state='retreat';e.timer=.5;}return;}if(e.state==='retreat'){e.x-=e.face*85*dt;if(!e.timer)e.state='approach';return;}
 const engaged=actors.filter(a=>a!==e&&!a.dead&&!a.inactive&&(a.state==='windup'||a.state==='strike')).length;if(e.role==='thrower'&&Math.abs(dx)>130&&Math.abs(dx)<330&&Math.abs(dy)<100&&e.timer===0){e.state='windup';e.timer=.8;e.throwing=true;return;}if(Math.abs(dx)<80&&Math.abs(dy)<70&&engaged<2){e.state='windup';e.timer=e.role==='bruiser'?.8:.55;e.throwing=false;return;}if(Math.abs(dx)>65){e.x+=Math.sign(dx)*e.speed*dt;e.vx=Math.sign(dx)*e.speed;}else e.vx=0;for(const a of actors)if(a!==e&&!a.dead&&!a.inactive&&Math.abs(a.x-e.x)<42)e.x+=(e.x>a.x?1:-1)*35*dt;e.x=Math.max(80,Math.min(2100,e.x));}
function brawlStep(dt){if(partner){partner.assistCd=Math.max(0,(partner.assistCd||0)-dt);const target=actors.find(e=>!e.dead&&!e.inactive&&Math.abs(e.x-partner.x)<95);if(target&&partner.assistCd<=0){partner.face=Math.sign(target.x-partner.x);partner.attack=.4;damage(target,.5);partner.assistCd=.8;}}for(const e of actors)if(e.state==='strike'&&e.throwing&&!e.thrown){e.thrown=true;bullets.push({x:e.x+17,y:e.y+25,vx:e.face*240,vy:-30,enemy:true,life:1.5,bottle:true});}for(const e of actors)if(e.state!=='strike')e.thrown=false;if(actors.filter(e=>e.wave===wave).every(e=>e.dead)&&wave<2){wave++;for(const e of actors)if(e.wave===wave)e.inactive=false;talk('Round '+(wave+1),wave===2?'The big one has a slow windup. Make him miss.':'They’re coming from both sides. Use the balcony.',4);}}
function drawMissionDetails(){if(chapter===0){for(const g of gates)if(!stationDone(g.requires)){const x=g.x-camera;if(selected==='sylvanas'){drawForestGate(g);continue;}rect(x,90,28,FLOOR-90,'#344555');for(let y=100;y<FLOOR;y+=22)rect(x+4,y,20,5,'#bd635a');label(g.name,x+14,80,'#eab17c',11);}for(const h of hazards){const active=!stationDone('cooling')&&(clock+h.phase)%4<1.15;for(let i=0;i<6;i++){ctx.globalAlpha=active?.38:.08;rect(h.x-camera+i*16,(h.y||452)-42-Math.sin(clock*6+i)*15,10,42,selected==='nova'?'#a8eff1':'#ac8fe2');}ctx.globalAlpha=1;}for(let i=0;i<6;i++)label((selected==='nova'?roomNames:forestNames)[i].toUpperCase(),roomBounds[i]+240-camera,115,'#829eae',13);}if(chapter===2){for(const [x,w] of [[500,150],[1100,170],[1750,120]]){rect(x-camera,414,w,8,'#8d6546');rect(x+12-camera,422,10,30,'#4c3429');rect(x+w-20-camera,422,10,30,'#4c3429');}for(const e of actors)if(!e.dead&&!e.inactive&&e.state==='windup'){label('!',e.x-camera+17,e.y-20,'#ffc278',24);rect(e.x-camera-6,e.y-9,46*(1-e.timer/(e.role==='bruiser'?.8:.55)),3,'#ffc278');}}}

function retryCheckpoint(){const state=chapter===0?checkpointState:null;const n=chapter;start(n);if(state){for(const o of objects)if(state.done.includes(o.id))o.done=true;player.x=state.x;const landing=solids.filter(p=>p.h>=50&&player.x+34>p.x&&player.x<p.x+p.w).sort((a,b)=>a.y-b.y)[0];player.y=(landing?.y||FLOOR)-86;player.vy=0;player.ground=true;cameraY=player.y>420?player.y-250:0;camera=Math.max(0,player.x-330);worldStep(0);talk('Checkpoint','Back on your feet, Captain. Completed controls remain unlocked.',3);}}
function buildIsland(n){const plans={5:{length:4600,routes:[[450,320,360],[980,240,500],[1580,330,260],[2120,260,480],[3020,300,440],[3740,240,430]],page:[2360,220],rescue:[3880,210]},6:{length:5000,routes:[[260,350,250],[840,270,400],[1470,190,410],[2090,300,380],[2780,220,500],[3620,330,370],[4210,260,350]],page:[1650,150],rescue:[4320,230]},7:{length:4800,routes:[[380,310,430],[1070,220,360],[1640,350,320],[2370,200,500],[3160,300,390],[3900,230,430]],page:[2590,160],rescue:[4000,200]},8:{length:5300,routes:[[230,340,370],[900,260,380],[1550,190,440],[2310,320,450],[3100,240,460],[3970,170,500],[4650,300,270]],page:[4140,130],rescue:[4760,270]}};const plan=plans[n];if(!plan)return;chapters[n].length=plan.length;solids=[{x:0,y:FLOOR,w:plan.length,h:110,kind:'wood'}];ladders=[];actors=[];covers=[];objects=[];for(const [x,y,w] of plan.routes){solids.push({x,y,w,h:17,kind:'wood'});ladders.push({x:x+30,y,h:FLOOR-y});actors.push({...enemy(x+w*.65,'pirate',4),y:y-84,origin:x+w*.65,range:Math.min(110,w/3)});covers.push({x:x+w*.4,y:FLOOR-70,w:65,h:70});}for(const x of [620,1330,2070,2920,3530,plan.length-650])actors.push(enemy(x,'pirate',4));for(let i=0;i<18;i++)objects.push({type:'coin',x:220+i*(plan.length-500)/18,y:FLOOR-35});for(const [x,y,w] of plan.routes)objects.push({type:'coin',x:x+w*.35,y:y-32});objects.push({type:'scrap',x:plan.page[0],y:plan.page[1]},{type:'rescue',x:plan.rescue[0],y:plan.rescue[1]},{type:'heart',x:1800,y:FLOOR-35},{type:'heart',x:3550,y:FLOOR-35});actors.push(enemy(plan.length-300,'pirate',16,true));}
